try {
  db.exec(`ALTER TABLE access_users ADD COLUMN status TEXT NOT NULL DEFAULT 'waiting_code'`);
} catch (_) {}
try {
  // Backfill status from verified_at for older rows
  db.exec(`
    UPDATE access_users
    SET status = CASE
      WHEN verified_at IS NOT NULL AND TRIM(verified_at) != '' THEN 'active'
      ELSE 'waiting_code'
    END
    WHERE status IS NULL OR status = '' OR status = 'waiting_code'
  `);
  db.exec(`
    UPDATE access_users
    SET status = 'active'
    WHERE verified_at IS NOT NULL AND TRIM(verified_at) != '' AND status != 'active'
  `);
} catch (_) {}
